16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * Derives an owner's numeric membership level from their {@link MembershipPoints}.
20	 *
21	 * <p>Points map to a level as follows: {@code 0-1} points is level {@value #MIN},
22	 * {@code 2-3} is level 2, {@code 4-5} is level 3, and {@code 6} or more is level
23	 * {@value #MAX}.
24	 */
25	public final class MembershipLevel {
26	
27	    /** The lowest level attainable. */
28	    public static final int MIN = 1;
29	
30	    /** The highest level attainable. */
31	    public static final int MAX = 4;
32	
33	    private MembershipLevel() {
34	    }
35	
36	    /**
37	     * Derive the membership level for the given owner.
38	     *
39	     * @param owner the owner (must not be {@code null}).
40	     * @return the level, from {@value #MIN} to {@value #MAX}.
41	     */
42	    public static int of(Owner owner) {
43	        return forPoints(MembershipPoints.of(owner));
44	    }
45	
46	    /**
47	     * Map a membership points total to its level.
48	     *
49	     * @param points the membership points (see {@link MembershipPoints}).
50	     * @return the level, from {@value #MIN} to {@value #MAX}.
51	     */
52	    public static int forPoints(int points) {
53	        if (points <= 1) {
54	            return 1;
55	        }
56	        if (points <= 3) {
57	            return 2;
58	        }
59	        if (points <= 5) {
60	            return 3;
61	        }
62	        return MAX;
63	    }
